"use client";
import { useSession } from "next-auth/react";
import { useEffect, useState } from "react";
import { Card, CardHeader, CardTitle, CardContent } from "components/ui/Card";
import { Button } from "@/components/ui/button";

export default function AdminDashboard() {
  const { data: session } = useSession();
  const [data, setData] = useState<any>(null);

  useEffect(() => {
    fetch("/api/admin/data").then(res => res.json()).then(setData);
  }, []);

  if (!data) return <div className="p-10 text-white">Yükleniyor...</div>;

  const isAdmin = session?.user?.role === "ADMIN";
  const isMedewerker = session?.user?.role === "MEDEWERKER";

  return (
    <div className="p-8 space-y-8 text-white">
      <h1 className="text-3xl font-black tracking-tighter text-blue-500 uppercase">
        {isAdmin ? "Sistem Kontrol Merkezi" : "Personel Paneli"}
      </h1>

      {/* 1. İSTATİSTİKLER (Sadece Admin Görebilir) */}
      {isAdmin && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {data.stats.map((user: any) => (
            <Card key={user.id} className="bg-white/5 border-white/10">
              <CardHeader>
                <CardTitle className="text-sm uppercase tracking-widest">{user.name}</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold text-fuchsia-500">{user.percentage}% Tamamlandı</div>
                <p className="text-xs text-white/40">{user.taskCount} Toplam Görev</p>
                <Button variant="destructive" size="xs" className="mt-4">Kullanıcıyı Sil</Button>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {/* 2. GELEN MESAJLAR (Admin ve Medewerker Görebilir) */}
      <div className="space-y-4">
        <h2 className="text-xl font-bold text-teal-400 uppercase italic">Gelen İletişim Formları</h2>
        <div className="border border-white/10 rounded-2xl overflow-hidden bg-black/20">
          <table className="w-full text-left text-sm">
            <thead className="bg-white/5 text-white/40 uppercase text-[10px]">
              <tr>
                <th className="p-4">Gönderen</th>
                <th className="p-4">Mesaj</th>
                <th className="p-4">Tarih</th>
                {isAdmin && <th className="p-4">İşlem</th>}
              </tr>
            </thead>
            <tbody>
              {data.messages.map((msg: any) => (
                <tr key={msg.id} className="border-t border-white/5 hover:bg-white/5 transition-colors">
                  <td className="p-4 font-bold">{msg.name} <br/><span className="text-[10px] opacity-40">{msg.email}</span></td>
                  <td className="p-4 text-white/60">{msg.message}</td>
                  <td className="p-4 text-[10px]">{new Date(msg.createdAt).toLocaleDateString()}</td>
                  {isAdmin && (
                    <td className="p-4">
                      <Button variant="ghost" size="xs" className="text-red-500">Sil</Button>
                    </td>
                  )}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}